CREATE DATABASE IF NOT EXISTS encuesta_graduados;
USE encuesta_graduados;
DROP TABLE IF EXISTS form_answers;
DROP TABLE IF EXISTS users; 

CREATE TABLE form_answers (
id INT UNSIGNED PRIMARY KEY NOT NULL AUTO_INCREMENT,
email VARCHAR (64) NOT NULL ,
identification_number VARCHAR (64) NOT NULL ,
name VARCHAR(64) NOT NULL,
last_name VARCHAR(64) NOT NULL,
mobile_phone VARCHAR(64) NOT NULL ,
alternative_mobile_phone VARCHAR(64),
address TEXT NOT NULL,
country VARCHAR(64) NOT NULL,
city VARCHAR(64) NOT NULL,
answers JSON NOT NULL,
is_graduated TINYINT NOT NULL,
is_migrated TINYINT DEFAULT 0,
is_denied TINYINT DEFAULT 0,
is_deleted TINYINT NOT NULL DEFAULT 0,
migrated_by INT,
denied_by INT,
deleted_by INT,
has_error TINYINT,
created_at DATETIME NOT NULL,
modificated_at DATETIME NOT NULL DEFAULT NOW() ON UPDATE NOW(),
updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);


CREATE TABLE users (
id INT UNSIGNED PRIMARY KEY NOT NULL AUTO_INCREMENT,
username VARCHAR(64),
role VARCHAR (64)
);


